/**
 * 스토리 진행도 관리
 *
 * - 누적 통계 (달린 거리, 토파즈 수집, 치비 플레이 횟수, SKOR 획득)를 localStorage에 djb2 서명으로 저장
 * - 잠금 해제 조건을 체크하고 새로 열린 로그 번호를 반환
 * - 서명 불일치 시 변조로 판단해 초기값으로 초기화
 */

import { getOwnedCharacters, CHARACTERS } from './character';
import { djb2 } from './signing';

// ── 타입 ──────────────────────────────────────────────────────────────────────

export interface StoryStats {
  totalDistance: number;       // 누적 달린 거리 (m, score 1점 = 1m)
  totalTopazCollected: number; // 누적 토파즈똥 수집 수
  chibiPlayCount: number;      // 치비 캐릭터로 플레이한 횟수
  totalSkorEarned: number;     // 누적 SKOR 획득량
}

// ── localStorage 키 / Salt ────────────────────────────────────────────────────

const STATS_KEY     = 'storyStats';
const STATS_SIG_KEY = 'storyStatsSig';
const LOGS_KEY      = 'storyLogs';
const LOGS_SIG_KEY  = 'storyLogsSig';

const _STATS_SALT = 'ddong-story-stats-\u0076\u0031';
const _LOGS_SALT  = 'ddong-story-logs-\u0076\u0031';

// ── 서명 ──────────────────────────────────────────────────────────────────────

function _signStats(s: StoryStats): string {
  return djb2(
    `${s.totalDistance}:${s.totalTopazCollected}:${s.chibiPlayCount}:${s.totalSkorEarned}` + _STATS_SALT
  );
}

function _signLogs(logs: number[]): string {
  return djb2([...logs].sort((a, b) => a - b).join(',') + _LOGS_SALT);
}

// ── 읽기 / 쓰기 ──────────────────────────────────────────────────────────────

const _DEFAULT_STATS: StoryStats = {
  totalDistance: 0,
  totalTopazCollected: 0,
  chibiPlayCount: 0,
  totalSkorEarned: 0,
};

function _loadStats(): StoryStats {
  try {
    const raw = localStorage.getItem(STATS_KEY);
    const sig = localStorage.getItem(STATS_SIG_KEY);
    if (!raw) return { ..._DEFAULT_STATS };

    const stats = JSON.parse(raw) as StoryStats;
    if (!sig) {
      // 서명 없음 → 기존 데이터 신뢰 후 서명 최초 발급
      _saveStats(stats);
      return stats;
    }
    if (sig !== _signStats(stats)) {
      // 서명 불일치 → 변조, 초기화
      _saveStats({ ..._DEFAULT_STATS });
      return { ..._DEFAULT_STATS };
    }
    return stats;
  } catch {
    return { ..._DEFAULT_STATS };
  }
}

function _saveStats(stats: StoryStats): void {
  localStorage.setItem(STATS_KEY, JSON.stringify(stats));
  localStorage.setItem(STATS_SIG_KEY, _signStats(stats));
}

function _loadLogs(): number[] {
  try {
    const raw = localStorage.getItem(LOGS_KEY);
    const sig = localStorage.getItem(LOGS_SIG_KEY);
    if (!raw) return [];

    const logs = JSON.parse(raw) as number[];
    if (!sig) {
      _saveLogs(logs);
      return logs;
    }
    if (sig !== _signLogs(logs)) {
      _saveLogs([]);
      return [];
    }
    return logs;
  } catch {
    return [];
  }
}

function _saveLogs(logs: number[]): void {
  localStorage.setItem(LOGS_KEY, JSON.stringify(logs));
  localStorage.setItem(LOGS_SIG_KEY, _signLogs(logs));
}

// ── 잠금 해제 조건 체크 ────────────────────────────────────────────────────────

/**
 * 현재 stats + 보유 캐릭터 기준으로 잠금 해제 가능한 로그를 체크.
 * @returns 새로 잠금 해제된 로그 번호 배열
 */
function _checkConditions(stats: StoryStats, unlockedLogs: number[]): number[] {
  const ownedCount = getOwnedCharacters().length;
  const newLogs: number[] = [];

  const unlock = (logNum: number, condition: boolean) => {
    if (condition && !unlockedLogs.includes(logNum)) {
      newLogs.push(logNum);
    }
  };

  unlock(1,  ownedCount >= 2);                            // 첫 번째 뽑기 완료
  unlock(2,  ownedCount >= 2);                            // 캐릭터 2명 보유
  unlock(3,  stats.totalDistance >= 500);                 // 달린 거리 500m
  unlock(4,  stats.totalSkorEarned >= 100);               // SKOR 100 누적 획득
  unlock(5,  ownedCount >= 3);                            // 캐릭터 3명 보유
  unlock(8,  stats.totalDistance >= 5000);                // 달린 거리 5000m
  unlock(9,  ownedCount >= 5);                            // 캐릭터 5명 보유
  unlock(10, stats.chibiPlayCount >= 50);                 // 치비 50회 플레이
  unlock(11, stats.totalTopazCollected >= 30);            // 토파즈 30개 수집
  unlock(12, stats.totalDistance >= 10000);               // 달린 거리 10000m
  unlock(13, ownedCount >= CHARACTERS.length);            // 전체 캐릭터 수집

  return newLogs;
}

function _applyNewLogs(newLogs: number[], currentLogs: number[]): void {
  if (newLogs.length === 0) return;
  _saveLogs([...currentLogs, ...newLogs]);
}

// ── 공개 API ──────────────────────────────────────────────────────────────────

/**
 * 게임 세션 완료 시 호출 (게임오버 시점).
 * score를 달린 거리(m)로 사용.
 * @returns 새로 잠금 해제된 로그 번호 배열
 */
export function recordGameSession(
  score: number,
  topazCollected: number,
  wasChibi: boolean,
): number[] {
  const stats = _loadStats();
  const logs  = _loadLogs();

  stats.totalDistance       += score;
  stats.totalTopazCollected += topazCollected;
  if (wasChibi) stats.chibiPlayCount += 1;

  _saveStats(stats);

  const newLogs = _checkConditions(stats, logs);
  _applyNewLogs(newLogs, logs);
  return newLogs;
}

/**
 * SKOR 획득 시 호출 (skor-submit 응답의 totalSkorAdded).
 * @returns 새로 잠금 해제된 로그 번호 배열
 */
export function recordSkorEarned(amount: number): number[] {
  if (amount <= 0) return [];

  const stats = _loadStats();
  const logs  = _loadLogs();

  stats.totalSkorEarned += amount;
  _saveStats(stats);

  const newLogs = _checkConditions(stats, logs);
  _applyNewLogs(newLogs, logs);
  return newLogs;
}

/**
 * 뽑기/캐릭터 획득 후 호출 (보유 수 기반 조건 체크).
 * @returns 새로 잠금 해제된 로그 번호 배열
 */
export function checkOwnershipConditions(): number[] {
  const stats = _loadStats();
  const logs  = _loadLogs();

  const newLogs = _checkConditions(stats, logs);
  _applyNewLogs(newLogs, logs);
  return newLogs;
}

/** 현재 잠금 해제된 로그 번호 목록 반환 */
export function getUnlockedLogs(): number[] {
  return _loadLogs();
}

/** 누적 통계 반환 (디버그/UI 표시용) */
export function getStoryStats(): StoryStats {
  return _loadStats();
}

