   274→/** duplicate_count → 각성 단계 계산 (모든 등급 최대 ★5) */
   275→export function getAwakeningLevel(grade: string, duplicateCount: number): number {
   276→  if (grade === 'R') {
   277→    if (duplicateCount >= 100) return 5;
   278→    if (duplicateCount >= 75)  return 4;
   279→    if (duplicateCount >= 50)  return 3;
   280→    if (duplicateCount >= 25)  return 2;
   281→    if (duplicateCount >= 10)  return 1;
   282→  } else if (grade === 'SR') {
   283→    if (duplicateCount >= 40) return 5;
   284→    if (duplicateCount >= 25) return 4;
   285→    if (duplicateCount >= 15) return 3;
   286→    if (duplicateCount >= 7)  return 2;
   287→    if (duplicateCount >= 3)  return 1;
   288→  } else if (grade === 'UR') {
   289→    if (duplicateCount >= 10) return 5;
   290→    if (duplicateCount >= 6)  return 4;
   291→    if (duplicateCount >= 4)  return 3;
   292→    if (duplicateCount >= 2)  return 2;
   293→    if (duplicateCount >= 1)  return 1;
   294→  }
   295→  return 0;
   296→}
   297→
   298→const DUPES_KEY     = 'duplicateCounts';
   299→const DUPES_SIG_KEY = 'duplicateCountsSig';
   300→const _DUPES_SALT   = 'ddong-dupes-\u0076\u0032';
   301→
   302→/** djb2 해시 — key:value 쌍을 정렬 후 직렬화해 서명 */
   303→function _signDupes(map: Record<string, number>): string {
   304→  const str = Object.entries(map)
   305→    .sort(([a], [b]) => a.localeCompare(b))
   306→    .map(([k, v]) => `${k}:${v}`)
   307→    .join(',') + _DUPES_SALT;
   308→  return djb2(str);
   309→}
   310→
   311→function _saveDupes(map: Record<string, number>): void {
   312→  localStorage.setItem(DUPES_KEY, JSON.stringify(map));
   313→  localStorage.setItem(DUPES_SIG_KEY, _signDupes(map));
   314→}
   315→
   316→/** 캐릭터별 중복 획득 횟수 반환. 서명 불일치 시 변조로 판단해 전체 초기화. */
   317→export function getDuplicateCount(id: string): number {
   318→  try {
   319→    const raw = localStorage.getItem(DUPES_KEY);
   320→    const sig = localStorage.getItem(DUPES_SIG_KEY);
   321→    const map: Record<string, number> = raw ? JSON.parse(raw) : {};
   322→
   323→    if (sig === null) {
   324→      // 서명 미존재 → 기존 데이터 마이그레이션: 신뢰하고 서명 최초 발급
   325→      _saveDupes(map);
   326→      return map[id] ?? 0;
   327→    }
   328→
   329→    // 서명 불일치 → 변조로 판단, 전체 초기화
   330→    if (sig !== _signDupes(map)) {
   331→      _saveDupes({});
   332→      return 0;
   333→    }
   334→
   335→    return map[id] ?? 0;
   336→  } catch {
   337→    return 0;
   338→  }
   339→}
   340→
   341→/** 캐릭터별 중복 획득 횟수 저장 (뽑기 완료 후 호출) */
   342→export function setDuplicateCount(id: string, count: number): void {
   343→  try {
   344→    const raw = localStorage.getItem(DUPES_KEY);
   345→    const sig = localStorage.getItem(DUPES_SIG_KEY);
   346→    const map: Record<string, number> = raw ? JSON.parse(raw) : {};
   347→
   348→    // 변조된 상태에서 쓰기 시도 → 기존 맵 무시하고 새로 시작
   349→    if (sig !== null && sig !== _signDupes(map)) {
   350→      _saveDupes({ [id]: count });
   351→      return;
   352→    }
   353→
   354→    map[id] = count;
   355→    _saveDupes(map);
   356→  } catch { /* ignore */ }
   357→}
   358→
   359→const OWNED_KEY = 'ownedCharacters';
   360→const OWNED_SIG_KEY = 'ownedCharactersSig';
   361→const SELECTED_KEY = 'selectedCharacter';
   362→const _SIG_SALT = 'ddong-v2-\u0073\u006b\u006f\u0072';
   363→
   364→/** djb2 해시 → base36 문자열 (무결성 서명용) */
   365→function _sign(list: string[]): string {
   366→  return djb2([...list].sort().join(',') + _SIG_SALT);
   367→}
   368→
   369→/** 보유 목록과 서명을 함께 저장 (내부 전용) */
   370→function _saveOwned(list: string[]): void {
   371→  localStorage.setItem(OWNED_KEY, JSON.stringify(list));
   372→  localStorage.setItem(OWNED_SIG_KEY, _sign(list));
   373→}
   374→
   375→/** 보유 캐릭터 목록 반환. 서명 불일치 시 변조로 판단하여 초기화. */
   376→export function getOwnedCharacters(): string[] {
   377→  try {
   378→    const raw = localStorage.getItem(OWNED_KEY);
   379→    const sig = localStorage.getItem(OWNED_SIG_KEY);
   380→    const list: string[] = raw ? JSON.parse(raw) : [];
   381→    if (!list.includes('chibi')) list.unshift('chibi');
   382→
   383→    if (sig === null) {
   384→      // 서명 미존재 → 기존 데이터 마이그레이션: 목록을 신뢰하고 서명 최초 발급
   385→      _saveOwned(list);
   386→      return list;
   387→    }
   388→
   389→    // 서명 존재하지만 불일치 → 변조로 판단, chibi만 남김
   390→    if (sig !== _sign(list)) {
   391→      _saveOwned(['chibi']);
   392→      return ['chibi'];
   393→    }
   394→
   395→    return list;
   396→  } catch {
   397→    return ['chibi'];
   398→  }
   399→}
   400→
   401→/** 서버 동기화 등 외부에서 목록 전체를 덮어쓸 때 사용 (서명 함께 갱신) */
   402→export function setOwnedCharacters(list: string[]): void {
   403→  if (!list.includes('chibi')) list.unshift('chibi');
   404→  _saveOwned(list);
   405→}
   406→
   407→/** 캐릭터를 보유 목록에 추가 (뽑기 완료 후 호출) */
   408→export function addOwnedCharacter(id: string): void {
   409→  const owned = getOwnedCharacters();
   410→  if (!owned.includes(id)) {
   411→    owned.push(id);
   412→    _saveOwned(owned);
   413→  }
   414→}
   415→
   416→/** 선택된 캐릭터 ID 반환. 없으면 'chibi'. */
   417→export function getSelectedCharacter(): string {
   418→  return localStorage.getItem(SELECTED_KEY) ?? 'chibi';
   419→}
   420→
   421→/** 선택된 캐릭터 저장 */
   422→export function setSelectedCharacter(id: string): void {
   423→  localStorage.setItem(SELECTED_KEY, id);
   424→}
   425→
   426→/** 소유 목록과 교차 검증하여 안전한 캐릭터 ID 반환. 미보유면 'chibi'로 강제 초기화. */
   427→export function getSafeSelectedCharacter(): string {
   428→  const selected = getSelectedCharacter();
   429→  const owned = getOwnedCharacters();
   430→  if (owned.includes(selected)) return selected;
   431→  // 변조 감지 → chibi로 강제 초기화
   432→  setSelectedCharacter('chibi');
   433→  return 'chibi';
   434→}
   435→
   436→/** 캐릭터 정의 조회 */
   437→export function getCharacterDef(id: string): CharacterDef {
   438→  return CHARACTERS.find(c => c.id === id) ?? CHARACTERS[0];
   439→}
